// Module 5 — Emerging & Future Technologies
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1 Remember · Q2 Understand · Q3 Apply · Q4 Apply · Q5 Analyze · Q6 Evaluate · Q7 Create
// All distractors are Grade A: every option is plausible.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Artificial Intelligence (Narrow, General, Super) ───
  1: [
    { q: "Which of the following is the correct definition of Artificial Intelligence?", opts: ["A physical robot with a metal body", "The ability of machines to simulate intelligent behaviour — perceiving, reasoning, learning, and acting", "Any computer connected to the internet", "A new kind of microchip"], ans: 1, why: "AI is defined by the BEHAVIOUR (intelligent-seeming action), not by a specific shape (robot) or hardware. Software can be AI; hardware alone is not.", bloom: "remember" },
    { q: "Why is today's AI classified as \"Narrow\" even when it beats humans at specific tasks?", opts: ["Because it's weak at everything", "Narrow AI is specialised: a chess AI masters chess but can't diagnose illness or drive a car. General AI would mean one system that handles ANY cognitive task a human can. Narrow ≠ weak; it means task-specific", "Because it uses less memory", "Because it's newer"], ans: 1, why: "Understanding Narrow vs General means seeing the difference is BREADTH, not strength. A narrow AI can be superhuman at its task AND still be narrow.", bloom: "understand" },
    { q: "Netflix recommending shows, Siri answering questions, and Tesla's autopilot are all examples of:", opts: ["General AI", "Narrow AI — each is designed for one specific task and cannot transfer to another", "Super AI", "Not AI at all"], ans: 1, why: "Applying the classification: each system excels in its domain but can't switch (Netflix can't drive, Siri can't diagnose cancer). That's the Narrow AI signature.", bloom: "apply" },
    { q: "A company claims their \"General AI\" system can write emails, book flights, and do accounting. Apply what you know — what's probably really happening under the hood?", opts: ["True General AI has arrived", "It's a set of Narrow AI tools (or one LLM with multiple tools attached) presented as if it were one system. Marketing often uses \"General AI\" loosely, but true General AI (human-level across ALL tasks) doesn't exist yet", "It's Super AI", "It's a trick — no AI involved"], ans: 1, why: "Applying skepticism means recognising that \"general\" in marketing usually means \"multi-tool narrow,\" not the academic definition of General AI. The student should spot the gap.", bloom: "apply" },
    { q: "A hospital claims their AI diagnoses cancer better than doctors. Analyse the trust gap between \"more accurate on test data\" and \"safe to deploy in real care.\"", opts: ["Accuracy is all that matters", "Issues: (a) test data may not represent edge cases in real patients, (b) AI can't explain its reasoning to patients, (c) mis-diagnoses need a chain of accountability that AI can't provide, (d) rare conditions may be underrepresented in training. High accuracy is necessary but not sufficient for deployment", "AI should replace all doctors", "Accuracy is always fake"], ans: 1, why: "Analysing deployment readiness means distinguishing lab performance from real-world safety. Accuracy, explainability, accountability, and coverage of edge cases all matter — a high score on one ignores the others.", bloom: "analyze" },
    { q: "Evaluate the claim: \"Since AI is getting smarter, universities should teach less and let AI tutors handle students.\"", opts: ["Correct — AI replaces teachers", "Flawed. AI tutors CAN personalise drill practice and explanations. But universities teach critical thinking, collaboration, ethics, and research — all areas where current AI hallucinates confidently or lacks lived context. The better framing: AI for practice + humans for judgment, not substitution", "Correct — teachers are obsolete", "AI tutors don't work"], ans: 1, why: "Evaluating the substitution argument requires distinguishing what AI does well (drill, feedback, availability) from what it doesn't (judgment, mentorship, complex research). The answer should name the split, not pick a side.", bloom: "evaluate" },
    { q: "Design an appropriate use of AI in a university classroom that supports learning without enabling cheating.", opts: ["Ban all AI", "Students can use AI for: brainstorming, explaining concepts, code review, practice quizzes. Must disclose AI use in submissions. Assessments include in-class oral components where AI can't help. AI literacy module teaches when to use and when to avoid. Policy separates using AI as a LEARNING TOOL (ok) from AI as a REPLACEMENT for thinking (cheating)", "Require AI for every assignment", "Ignore the issue"], ans: 1, why: "Designing an AI-in-education policy means drawing a usable line: AI as learning aid vs AI as output substitute. Disclosure, oral components, and AI-literacy instruction are the policy tools that make the line enforceable.", bloom: "create" },
  ],

  // ─── Topic 2: Machine Learning (Supervised, Unsupervised, Reinforcement) ───
  2: [
    { q: "Which statement correctly distinguishes the three main types of Machine Learning?", opts: ["They are synonyms", "Supervised learns from labelled examples; Unsupervised finds patterns in unlabelled data; Reinforcement learns through trial, reward, and penalty", "Only Supervised is real", "ML doesn't have types"], ans: 1, why: "The three-way split is the canonical ML taxonomy: labelled (supervised), unlabelled (unsupervised), reward-based (reinforcement). Each suits different data and goals.", bloom: "remember" },
    { q: "Why does more data usually help a machine learning model — up to a point?", opts: ["Data is magic", "Models learn patterns by seeing examples. More examples = more chances to distinguish signal from noise = better generalisation. But: after sufficient data, returns diminish (the model has seen the relevant patterns), and bad-quality data hurts more than it helps", "More data always helps", "More data always hurts"], ans: 1, why: "Understanding the data-quantity relationship means knowing it's a curve, not a line. Early data is gold; late marginal data is mostly noise; bad data is strictly negative. More-is-better has limits.", bloom: "understand" },
    { q: "Gmail's spam filter uses data labelled by users as \"spam\" or \"not spam\" to improve. Which ML type?", opts: ["Unsupervised", "Supervised — labels (spam/not-spam) teach the model the correct classification", "Reinforcement", "None — just rules"], ans: 1, why: "Applying the taxonomy: when each training example has a known correct answer (label), that's Supervised. Users flagging emails is the labelling step.", bloom: "apply" },
    { q: "A retailer wants to segment customers into groups WITHOUT being told the categories ahead of time. Which ML type?", opts: ["Supervised", "Unsupervised — the model finds natural clusters in the data on its own", "Reinforcement", "None"], ans: 1, why: "Applying the taxonomy: no labels, just raw data → the model groups similar items without a predefined \"correct\" answer. That's Unsupervised, specifically clustering.", bloom: "apply" },
    { q: "A facial recognition model works well on training data (90%+) but badly on faces it has never seen (60%). Analyse.", opts: ["Random bad luck", "Overfitting: the model memorised training-set specifics instead of learning generalisable features. Fixes: more diverse training data, regularisation, simpler model, cross-validation. High train accuracy + low test accuracy is the textbook overfitting signature", "The model is perfect", "Deep learning always does this"], ans: 1, why: "Analysing the train/test gap identifies overfitting as the cause. Naming fixes (diverse data, regularisation) shows real understanding beyond just naming the problem.", bloom: "analyze" },
    { q: "A company argues: \"We should always prefer supervised learning — labels make it more accurate.\" Evaluate.", opts: ["Correct — always use supervised", "Flawed. Supervised needs labels, which are expensive (human annotation time) and may not exist. For customer segmentation, anomaly detection, or exploring unknown structure, unsupervised is the right tool. Reinforcement fits problems with sequential decisions + delayed reward (games, robotics). Match the method to the problem, not the other way around", "Correct — labels are free", "All methods are identical"], ans: 1, why: "Evaluating the \"always supervised\" preference requires knowing when supervised FAILS: when labels don't exist or cost too much, or when the structure of the problem is sequential/exploratory. Method choice follows problem shape.", bloom: "evaluate" },
    { q: "Design an ML approach for a bank that wants to detect credit-card fraud. Which ML type(s), what data, and what challenges?", opts: ["No ML needed", "Hybrid: Supervised for known fraud patterns (labelled historical fraud cases) + Unsupervised anomaly detection for novel fraud patterns (outliers relative to a user's history). Data: transaction amount, location, time, merchant, device. Challenges: extremely imbalanced classes (fraud is rare), adversarial actors evolving tactics, false-positive cost on legitimate customers. Human review tier before blocking", "Just block everything suspicious", "Use only unsupervised"], ans: 1, why: "Designing a real ML system means naming the method(s), the data, and the challenges (imbalanced classes, adversarial adaptation, false positives). Hybrid approaches beat single-method choices for evolving threats.", bloom: "create" },
  ],

  // ─── Topic 3: Data Analytics (Descriptive, Diagnostic, Predictive, Prescriptive) ───
  3: [
    { q: "Which ordering correctly ranks the four types of analytics from simplest to most advanced?", opts: ["Prescriptive → Predictive → Diagnostic → Descriptive", "Descriptive → Diagnostic → Predictive → Prescriptive", "Diagnostic → Descriptive → Predictive → Prescriptive", "Predictive → Descriptive → Prescriptive → Diagnostic"], ans: 1, why: "The canonical ladder: Descriptive (what happened) → Diagnostic (why) → Predictive (what will) → Prescriptive (what should we do). Each builds on the prior.", bloom: "remember" },
    { q: "Why is Prescriptive Analytics considered the most advanced of the four?", opts: ["It uses the fastest computers", "It doesn't just describe, explain, or predict — it RECOMMENDS specific actions, combining analysis with decision logic and often optimisation or AI. Acting on recommendations carries higher stakes than reporting numbers", "It was invented most recently", "It doesn't actually exist"], ans: 1, why: "Understanding the ladder: each step adds capability. Prescriptive is \"here's what to do,\" which requires all prior types plus action logic. The stakes and complexity compound.", bloom: "understand" },
    { q: "A monthly report showing \"Q1 revenue was $2.1M, down 8% from Q4\" is which type of analytics?", opts: ["Predictive", "Descriptive — it describes what happened, without asking why, forecasting, or recommending", "Prescriptive", "Diagnostic"], ans: 1, why: "Applying the taxonomy: past facts, no causal analysis or forecast = Descriptive. It's the foundation layer every other analytics builds on.", bloom: "apply" },
    { q: "A retailer's AI says: \"Launch a 15% discount on bedroom furniture starting April 1 to clear inventory before the May 1 price reset.\" Which type?", opts: ["Descriptive", "Prescriptive — it recommends a specific action, timing, and magnitude", "Predictive", "Diagnostic"], ans: 1, why: "Applying the taxonomy: specific action recommendation + timing = Prescriptive. Predictive would stop at \"inventory will be high\"; prescriptive completes the loop with what to do.", bloom: "apply" },
    { q: "A company uses descriptive reports to say \"sales dropped 20%\" but never investigates why. Analyse the consequences of skipping Diagnostic Analytics.", opts: ["No consequences", "They know a fact but not a cause. Without Diagnostic, they can't target fixes — any action is a guess. Next quarter the drop repeats because the cause is unaddressed. Descriptive without Diagnostic is like a thermometer without a diagnosis: it tells you you're sick, not why", "Diagnostic is optional", "Descriptive alone is enough"], ans: 1, why: "Analysing the skipped step: the gap between \"what\" and \"why\" is where value is created. Descriptive alone produces reporting theatre; diagnostic turns facts into causes you can act on.", bloom: "analyze" },
    { q: "A startup debates whether to invest in Predictive Analytics or just keep doing Descriptive. Evaluate.", opts: ["Always skip Predictive", "Depends on decision stakes. If they're making recurring decisions (inventory, staffing, marketing spend) whose outcome depends on future demand, Predictive pays for itself fast. If decisions are one-off or low-stakes, Descriptive is fine. Don't invest in Predictive for its own sake — invest when forecasts drive real decisions", "Always use Predictive for everything", "Both are useless"], ans: 1, why: "Evaluating the investment decision requires tying it to decision stakes. Predictive is valuable when forecasts DRIVE action; it's overhead when they don't. The answer should name the criterion.", bloom: "evaluate" },
    { q: "Design a 4-step analytics plan for a university that wants to improve graduation rates (currently 70%).", opts: ["Just hope for the best", "1. Descriptive: current graduation rate per department, cohort, demographics. 2. Diagnostic: which factors correlate with dropouts — grades, attendance, financial aid, first-year performance. 3. Predictive: flag at-risk students early each semester based on diagnostic factors. 4. Prescriptive: design targeted interventions (tutoring, financial counselling, mentoring) for flagged students. Measure outcome against baseline", "Cancel the university", "Only use descriptive"], ans: 1, why: "Designing a full-stack analytics plan means using all four types in order: measure → explain → forecast → intervene. Skipping any layer leaves value on the table. The final measurement loop closes the feedback.", bloom: "create" },
  ],

  // ─── Topic 4: Cloud Computing (SaaS, PaaS, IaaS, Deployment Models) ───
  4: [
    { q: "Which statement correctly distinguishes SaaS, PaaS, and IaaS?", opts: ["They are the same", "SaaS = finished software you use (Gmail, Netflix). PaaS = platform to build on (Heroku, Vercel). IaaS = raw infrastructure to configure (AWS EC2, bare servers). Each gives up less control in exchange for less maintenance", "All three are paid versions of the same thing", "SaaS is hardware"], ans: 1, why: "The three-tier model: SaaS users just use; PaaS users build apps on a managed platform; IaaS users build platforms on raw infrastructure. Ladder of abstraction, ladder of control.", bloom: "remember" },
    { q: "Why does cloud computing use the \"hotel\" analogy? What does the hotel represent vs. a house?", opts: ["No real reason", "House = owning on-prem servers (you buy, maintain, repair, secure). Hotel = renting cloud resources (someone else maintains; you pay for what you use; scale up/down at will). The analogy captures cost model, maintenance burden, and flexibility", "It's just marketing", "Clouds have nothing to do with hotels"], ans: 1, why: "The analogy compresses three real trade-offs (CapEx vs OpEx, maintenance burden, scaling flexibility) into a picture students already understand. Ownership has control; renting has flexibility.", bloom: "understand" },
    { q: "A student group wants to build and host a study app without managing servers. They'll write code and deploy. Which cloud service model fits best?", opts: ["IaaS", "PaaS — provides the platform (runtime, scaling, database) so they only write the app code", "SaaS", "No cloud at all"], ans: 1, why: "Applying the three tiers: they want to build (not just use SaaS) but don't want to configure OS/networking (so IaaS is overkill). PaaS hits the middle.", bloom: "apply" },
    { q: "A hospital is choosing a cloud deployment model for patient records that are legally sensitive. Which model and why?", opts: ["Public Cloud — cheapest", "Private Cloud or Hybrid — dedicated infrastructure (or on-prem private portion) keeps sensitive data under stricter control and meets regulations. Public cloud can host the less-sensitive web front-end (Hybrid pattern)", "Multi-cloud only", "No cloud"], ans: 1, why: "Applying cloud model selection: sensitive + regulated data → Private or Hybrid. Public has its place for non-sensitive workloads; the sensitive data needs either isolation or a compliant region/contract.", bloom: "apply" },
    { q: "A startup built entirely on one cloud provider finds their bill doubling every 6 months as traffic grows. Analyse likely root causes.", opts: ["Cloud is always a scam", "Common causes: (a) missing auto-scaling rules so VMs run 24/7 at peak size, (b) no budget alerts so unused resources accumulate, (c) egress (data out) charges scale with users, (d) using premium instance types by default, (e) storage snapshots accumulating forever. Each is fixable; \"bill is growing\" is a signal to audit, not to blame the cloud", "Traffic always doubles costs", "Switch to on-prem"], ans: 1, why: "Analysing cloud bill growth means listing real cost drivers. Most runaway bills come from misconfiguration or missing hygiene, not from the cloud being inherently expensive. Naming multiple causes shows real understanding.", bloom: "analyze" },
    { q: "A CTO argues: \"Move everything to the cloud — it's always cheaper than buying hardware.\" Evaluate.", opts: ["Correct — always migrate", "Flawed. Cloud is cheaper for variable workloads (traffic spikes, early-stage startups) but CAN be more expensive for steady, high-utilisation workloads (a 24/7 database server may be cheaper on-prem over 3 years). The right answer: hybrid based on workload shape, not blanket migration", "Correct — hardware is obsolete", "Cloud is always more expensive"], ans: 1, why: "Evaluating the \"always cloud\" claim means knowing cloud economics: elastic and variable = win. Steady and predictable = often worse. Large enterprises run hybrid for exactly this reason.", bloom: "evaluate" },
    { q: "Design the cloud architecture for a small e-commerce site: website, product database, image hosting, payment processing, email receipts.", opts: ["Everything on one server", "Website: PaaS (Vercel/Heroku) — fast deploy. Database: managed DB (AWS RDS, Supabase) — backups + scaling handled. Images: object storage (S3, Cloudinary) — cheap per-GB. Payments: SaaS (Stripe) — PCI compliance outsourced. Email: SaaS (SendGrid/Resend) — deliverability handled. Each part uses the right service tier", "Just use one SaaS for everything", "On-prem only"], ans: 1, why: "Designing a modern cloud architecture means picking the right service tier for each concern: PaaS for custom code, managed DB for data, object storage for media, SaaS for regulated/specialised concerns. A monolith on one server leaves value and reliability on the table.", bloom: "create" },
  ],

  // ─── Topic 5: Blockchain ───
  5: [
    { q: "Which statement correctly describes blockchain?", opts: ["A new kind of cryptocurrency", "A decentralised, distributed ledger where transactions are recorded in linked blocks across many computers; once recorded, entries are practically immutable", "A cloud storage service", "A programming language"], ans: 1, why: "Blockchain is the underlying data structure / distribution pattern. Bitcoin is ONE cryptocurrency that uses it, not blockchain itself.", bloom: "remember" },
    { q: "Why is a blockchain considered \"immutable\" in practice, even though every entry could theoretically be changed?", opts: ["Magic", "Each block includes a cryptographic hash of the previous block. Changing block #500 changes its hash, which invalidates block #501's reference, which invalidates #502's, etc. To successfully rewrite one block, an attacker must rewrite every block after it AND convince >50% of the network, which is computationally infeasible at scale", "The government prevents changes", "Blocks are physically locked"], ans: 1, why: "Understanding immutability means understanding the hash-chain mechanism: one change cascades through the rest, and the distributed consensus makes cascading changes impractical. Not literally impossible, but economically infeasible.", bloom: "understand" },
    { q: "A supply chain uses blockchain to track coffee from farm to cup. Apply what you know — which property of blockchain makes this valuable?", opts: ["Speed", "Immutable audit trail: every handoff (farmer → processor → shipper → roaster → store) is recorded and can't be retroactively altered. Consumers can trace a cup back to its origin; disputes have a tamper-resistant record", "Low cost", "Blockchain isn't useful here"], ans: 1, why: "Applying blockchain's strengths to a scenario: provenance tracking + dispute resolution depends on an unchangeable record. That's exactly what blockchain provides, minus the cryptocurrency angle.", bloom: "apply" },
    { q: "A real estate platform claims to use blockchain so that \"home ownership records can never be lost or forged.\" Apply your knowledge — is this the primary benefit?", opts: ["Yes, blockchain is magic", "Real benefit is immutability + distribution (many independent copies of the record). But blockchain doesn't solve the \"off-chain\" problem: someone still has to correctly enter who owns the home, and legal title still flows through courts. Blockchain secures the record; it doesn't replace institutions", "No, blockchain is useless", "Only for Bitcoin"], ans: 1, why: "Applying realistic boundaries: blockchain secures records once correctly entered and distributed, but it doesn't verify reality. A student who understands this avoids over-claiming.", bloom: "apply" },
    { q: "A country proposes blockchain-based voting, arguing it will be \"fraud-proof.\" Analyse the real-world limits.", opts: ["Perfect solution", "Limits: (1) Voter authentication (who's at the keyboard?) is outside the blockchain. (2) Private ballot + public ledger are in tension. (3) 51% attacks on small chains are real. (4) Coercion (someone watching you vote at home) isn't prevented. (5) Software bugs in clients can undermine integrity. Blockchain solves some attack vectors while introducing others", "Blockchain is always fraud-proof", "Only paper voting works"], ans: 1, why: "Analysing blockchain voting means identifying the specific problems it does and doesn't solve. \"Immutable record\" ≠ \"correct record.\" Authentication, privacy, coercion, and software all sit outside the chain.", bloom: "analyze" },
    { q: "A founder pitches \"a blockchain-based social network where your posts can never be deleted.\" Evaluate.", opts: ["Brilliant", "Mostly flawed. (1) Content moderation becomes impossible — illegal or harmful posts stay forever. (2) Privacy regulation (GDPR right-to-deletion) conflicts directly. (3) Storage costs of permanent media are high. (4) The \"censorship-resistant\" feature users want is a legal/compliance nightmare for operators. Immutability is sometimes the bug, not the feature", "Blockchain everything", "Impossible"], ans: 1, why: "Evaluating a \"blockchain-for-everything\" pitch requires knowing that immutability itself can be a liability. Not every domain benefits from permanence; some (content moderation, PII) need deletion as a feature.", bloom: "evaluate" },
    { q: "Design a legitimate, high-value blockchain use case for a small country's government. Why blockchain specifically, vs. a regular database?", opts: ["Blockchain everything", "Property registry: (a) records must be tamper-evident across political transitions, (b) multiple departments need read access without central bottleneck, (c) citizens benefit from transparent provenance for disputes. Blockchain's immutability + distribution beats a central DB that any single authority could rewrite. Use case: yes. Shoehorning into everything: no", "Voting", "Social media"], ans: 1, why: "Designing a blockchain use case means proving the match: does this problem need immutability + distribution? Property records across political change are a strong fit; many other proposed uses aren't. Design = justification, not hype.", bloom: "create" },
  ],

  // ─── Topic 6: Virtual Reality ───
  6: [
    { q: "Which statement correctly defines Virtual Reality?", opts: ["Overlays digital objects onto the real world", "A fully computer-generated environment that replaces the user's view of the real world, experienced through a headset", "Any 3D video game on a screen", "A type of phone filter"], ans: 1, why: "VR = complete replacement of reality. The first option describes AR (which overlays), the third is 3D graphics (not immersive), the fourth is a filter.", bloom: "remember" },
    { q: "Why does VR feel more \"present\" than watching a 3D movie, even if both show the same content?", opts: ["VR has better pixels", "VR tracks your head (and often hands) in real time, so the scene responds to your motion. Combined with stereoscopic depth, spatial audio, and a blocked-out real world, the brain accepts the scene as a place you're IN rather than watching. 3D movies lack head tracking — you're still a seated viewer", "Movies don't use 3D", "They feel identical"], ans: 1, why: "Understanding VR presence means recognising head tracking + blocking reality as the key ingredients. Pixels alone don't make presence; the loop between motion and view does.", bloom: "understand" },
    { q: "A medical school wants to teach emergency surgery procedures safely. Apply what you know — why VR fits this need better than simulation on a flat screen?", opts: ["VR is cheaper", "In VR, students stand at a simulated operating table, see the patient from natural angles, and manipulate instruments with tracked controllers. Muscle memory + spatial context transfers to real procedures in ways a flat-screen tutorial can't reproduce. The immersion is the teaching tool", "Flat screens are better", "VR doesn't help"], ans: 1, why: "Applying VR's strengths: spatial skill transfer, stress inoculation, unlimited repetition without patient risk. Medical training is one of VR's clearest genuine value-adds.", bloom: "apply" },
    { q: "A real estate agent wants to show out-of-town buyers 5 homes in 30 minutes. Apply what you know — how does VR help, and what's a limit?", opts: ["VR replaces visits", "Helps: virtual walkthroughs give spatial sense that flat photos can't, saving time before in-person shortlisting. Limits: VR can't convey neighbourhood feel, smells, sunlight at different times, or unseen issues (water damage). Best use: pre-screen to shortlist, not replace in-person purchase decisions", "VR works perfectly", "VR is useless"], ans: 1, why: "Applying VR realistically means naming BOTH the value (spatial preview, time saved) and the limit (can't replace full in-person experience). The agent should use VR to narrow, not to close.", bloom: "apply" },
    { q: "Users report motion sickness after 20 minutes of VR. Analyse the likely causes.", opts: ["VR is broken", "Common causes: (a) low frame rate — the display can't keep up with head motion, creating a mismatch between visual motion and inner-ear signals. (b) Artificial locomotion (using a thumbstick to \"walk\") while physically still — strong cause of simulator sickness. (c) Latency between head motion and scene update. Fixes: 90+ fps, teleport locomotion, reduced latency, breaks every 20 min", "User is weak", "VR never causes this"], ans: 1, why: "Analysing VR sickness means identifying the sensory conflict: what you SEE moves, what you FEEL doesn't. Frame rate, locomotion style, and latency each contribute. Good analysis names multiple causes, not just one.", bloom: "analyze" },
    { q: "A school considers replacing field trips with VR field trips \"to save budget.\" Evaluate.", opts: ["Always replace with VR", "Partly valuable. VR can visit places impossible or unsafe to reach (Mars, inside a volcano, historical sites at a specific time). BUT social experience, chaperoned peer learning, real-world problem solving, and chance encounters don't transfer. Best fit: VR ADDS field trips, not replaces them. Total replacement trades one learning mode for another — not an upgrade", "Never use VR", "Budget is all that matters"], ans: 1, why: "Evaluating the trade-off requires listing what VR genuinely adds (access to impossible places) and what it loses (social, unpredictable, real-world). Replacement ≠ expansion; the right answer names both.", bloom: "evaluate" },
    { q: "Design a 45-minute VR lesson teaching 12-year-olds about the Roman Forum. What would they see, do, and leave with?", opts: ["Just show a video in VR", "Open: stand in the modern ruin, see overlaid reconstruction (AR-like). Explore: walk through key buildings, click hotspots for 1-min explanations (Senate, Temple of Saturn, Rostra). Interact: participate in a mock Senate vote (agree/disagree on a policy). Checkpoint: quiz embedded in the scene (\"where would a speech happen?\"). Reflect: take a journal photo back to class. Outcome: spatial memory + engagement impossible from textbooks, with structured assessment", "Random VR walk", "No VR — just talk"], ans: 1, why: "Designing a VR lesson means structuring exploration + interaction + assessment inside the medium, not just showing content. Named phases (open, explore, interact, check, reflect) show real instructional design.", bloom: "create" },
  ],

  // ─── Topic 7: Augmented Reality ───
  7: [
    { q: "Which statement correctly distinguishes AR from VR?", opts: ["They are identical", "VR replaces the real world entirely with a virtual one (headset blocks reality). AR overlays digital elements onto the real world (phone camera or transparent glasses — reality still visible)", "AR is for games only", "VR is always cheaper"], ans: 1, why: "The key axis is whether reality remains visible. VR blocks it; AR augments it. Same underlying technology (3D, tracking) but opposite relationship with the real world.", bloom: "remember" },
    { q: "Why is AR typically more practical than VR for everyday tasks like navigation or shopping?", opts: ["AR is cheaper", "AR keeps you aware of the real environment — you can walk down a street with directions overlaid, or place virtual furniture in YOUR room. VR isolates you, which is fine for immersion but impractical for tasks tied to real locations and objects", "VR doesn't work", "They're identical for practical use"], ans: 1, why: "Understanding the practical gap: VR's strength (total immersion) becomes a weakness when the task requires real-world awareness. AR's \"additive\" approach fits daily tasks naturally.", bloom: "understand" },
    { q: "IKEA's app lets you place a virtual sofa in your living room via phone camera. Which technology, and what real user problem does it solve?", opts: ["VR — blocks your room", "AR — overlays 3D sofa onto live camera feed. Problem: \"will this fit and look right?\" — previously required guessing or measuring; now previewed in seconds with accurate scale", "Blockchain", "Not a real app"], ans: 1, why: "Applying AR: the real-world anchor IS the user's room. AR places the virtual object in true scale, solving a real purchase decision that static photos can't.", bloom: "apply" },
    { q: "A surgeon uses AR glasses to see patient imaging data overlaid on the operating site. Apply what you know — why AR (not VR) is correct here.", opts: ["VR would be better", "The surgeon must see the REAL patient with REAL instruments; any vision of the actual site is non-negotiable. AR adds information (MRI scan aligned to anatomy) without blocking reality. VR would literally blind the surgeon", "AR is just for games", "Neither is useful"], ans: 1, why: "Applying tool fit: reality-critical tasks NEED reality visible. AR is the only option; VR is dangerous in this context. Naming the reason ties it to the AR/VR distinction.", bloom: "apply" },
    { q: "An AR museum guide overlays labels on paintings via phone. Users complain labels jitter and misalign. Analyse.", opts: ["Users are wrong", "Causes: (a) tracking loses the painting when the phone moves fast — AR relies on visual anchors. (b) Lighting changes (glare, shadow) confuse the recognition model. (c) Mobile GPS is imprecise indoors — alone can't anchor. Fixes: better markers on paintings, improved tracking model, fallback to manual QR-scan if tracking fails", "AR is always jittery", "Phone is broken"], ans: 1, why: "Analysing AR tracking failures means understanding how AR anchors virtual content to physical space (visual features + sensors). When the anchor fails, overlay drifts. Naming causes + fixes shows real understanding.", bloom: "analyze" },
    { q: "A startup proposes AR glasses that show contextual info (names, notes) on people you meet. Evaluate the product.", opts: ["Brilliant idea", "Flawed. Technically possible; socially and legally fraught. (1) Facial recognition on strangers is illegal in many regions. (2) Consent: the person being scanned hasn't agreed. (3) Trust: would people tolerate AR-wearers at their events? (4) Hallucinated \"facts\" about strangers create serious harm. The tech can work; the product likely can't ship in most markets", "Always build it", "Impossible tech"], ans: 1, why: "Evaluating an AR product means looking beyond \"does it work\" to \"should it exist.\" Privacy, consent, legal, and social factors decide product viability as much as engineering does.", bloom: "evaluate" },
    { q: "Design an AR learning app for medical students practicing anatomy. What do they see, do, and learn?", opts: ["Just a VR room", "Students wear AR glasses and look at a physical mannequin (or empty surface). Overlay: real-scale 3D human body. Interactions: peel layers (skin → muscle → organs → bones), rotate, quiz self on structures by tapping. Instructor mode: highlight structures for the class. Outcome: spatial anatomy understanding while students see each other, discuss, and physically gesture — social + spatial learning VR would isolate", "Show PDF in AR", "No tech"], ans: 1, why: "Designing an AR learning experience means leveraging what AR uniquely enables: spatial overlays on real shared space, which supports collaborative learning VR isolates. A named interaction set + outcome shows real design.", bloom: "create" },
  ],

  // ─── Topic 8: Internet of Things (IoT) ───
  8: [
    { q: "Which of the following best defines an IoT device?", opts: ["Any device plugged into electricity", "A physical object with embedded sensors, processing, and internet connectivity that collects and exchanges data with other systems", "Any device with a screen", "A new kind of router"], ans: 1, why: "IoT requires all three: sensing (or actuating), processing, and connectivity. A plain lamp is not IoT; a lamp with a temperature sensor that reports to an app is.", bloom: "remember" },
    { q: "Why is the IoT pipeline commonly described as Collect → Connect → Process → Act?", opts: ["Rhyming", "Those are the distinct stages every IoT system goes through: sensors collect data, connectivity sends it, a processor (edge or cloud) analyses, and an action follows (notification, actuator change, stored record). Skipping any stage breaks the system", "It's one step", "Steps happen in random order"], ans: 1, why: "Understanding the pipeline means seeing each stage as necessary and sequential. Collecting without connectivity is isolated data; processing without acting is reporting without value.", bloom: "understand" },
    { q: "A smart thermostat adjusts heating based on whether anyone is home. Map its behaviour to the IoT pipeline.", opts: ["All one step", "Collect: motion sensors + temperature sensor. Connect: sends data to home cloud. Process: algorithm decides if heating should be on. Act: actuator turns heating on/off. A clean 4-step IoT loop", "No IoT involved", "Thermostats aren't IoT"], ans: 1, why: "Applying the pipeline to a concrete device clarifies the stages. The same pipeline underlies every IoT system, from thermostats to industrial sensors.", bloom: "apply" },
    { q: "A farmer wants IoT for precision irrigation. Apply the pipeline — what sensors, what processing, what actions?", opts: ["Just water normally", "Collect: soil-moisture sensors per field section, weather station, satellite imagery. Connect: LoRa or cellular to farm server. Process: compare moisture vs. crop-specific thresholds; factor in forecast rain. Act: open/close valves per section; log for later analysis. Outcome: water only where needed, saving cost + yield", "Buy more tractors", "IoT doesn't work in farming"], ans: 1, why: "Applying the pipeline to design: naming sensors, processing rules, AND actions turns a vague idea into a system. Good application shows depth at every stage.", bloom: "apply" },
    { q: "A company deploys 10,000 IoT sensors on a factory floor. Six months later, they're a security nightmare. Analyse the root causes.", opts: ["IoT is always insecure", "Common causes: (a) default passwords never changed on many devices, (b) no firmware update mechanism — vulnerabilities compound over time, (c) flat network — compromise one device, reach all. (d) data sent unencrypted, (e) no monitoring for abnormal traffic. Fix: require password rotation, OTA updates, network segmentation, encryption, anomaly detection", "10,000 is too many", "Only cloud IoT fails"], ans: 1, why: "Analysing IoT security failures means listing the real operational problems. Each cause is fixable; \"IoT is insecure\" is a dodge. The analysis should produce an actionable fix list.", bloom: "analyze" },
    { q: "A parent considers putting IoT cameras in every room of the house \"for safety.\" Evaluate.", opts: ["Always do it", "Flawed. Benefits (deterrence, monitoring) are real but come with costs: (a) camera manufacturers can be breached, exposing home video, (b) family members' privacy, (c) false sense of security replacing better physical measures. Better: specific cameras at entry points, no bedrooms/bathrooms, strong passwords, local-only recording if possible", "Never", "Cameras are always safe"], ans: 1, why: "Evaluating home IoT requires weighing benefit against privacy + risk. \"For safety\" is a goal, not a justification for every placement. The answer should name trade-offs and propose a middle path.", bloom: "evaluate" },
    { q: "Design an IoT-based smart classroom for a Tashkent school. What devices, what data, what actions — and what to NOT do?", opts: ["Install 100 cameras", "Devices: air-quality sensor (CO2), temperature/humidity, door-open sensor, projector control, smart lights, attendance via opt-in student ID tap. Data: logs for maintenance, CO2 to ventilate automatically, attendance summary. Actions: auto-ventilate at CO2 threshold, pre-heat before class, alert maintenance if projector down. DO NOT: track individual students' location or listen to audio — privacy violation outweighs any benefit", "Everything on students", "No IoT"], ans: 1, why: "Designing ethically-bounded IoT means listing both the \"what to build\" and \"what to avoid.\" Naming the line (classroom monitoring OK; individual surveillance not OK) is what separates engineering from responsible engineering.", bloom: "create" },
  ],

  // ─── Topic 9: Generative AI ───
  9: [
    { q: "Which statement best distinguishes Generative AI from traditional AI?", opts: ["They are synonyms", "Traditional AI classifies, predicts, or recommends from existing data. Generative AI CREATES new content (text, images, audio, video, code) that didn't exist before, based on patterns in training data", "Generative AI is slower", "Generative AI only works with text"], ans: 1, why: "The key axis is production vs. classification. Classifying an email as spam is traditional; writing a new email is generative. Both use ML under the hood but differ in output type.", bloom: "remember" },
    { q: "Why does ChatGPT sometimes produce confident-sounding false information (\"hallucinations\")?", opts: ["Random bug", "LLMs generate the statistically most likely next token given the context. They optimise for plausibility, not truth. When asked about obscure or post-training facts, the model produces confident text that matches the PATTERN of truth without any truth-checking mechanism. Hallucination is a feature of the generation process, not a bug", "It's a bug Anthropic will fix", "LLMs always tell the truth"], ans: 1, why: "Understanding hallucination means seeing that LLMs model language patterns, not facts. Confidence is a property of fluent language, not of verified knowledge. This is why fact-checking matters.", bloom: "understand" },
    { q: "A student is writing an essay on WWII. Apply what you know about Generative AI — how should they use it?", opts: ["Have ChatGPT write the whole essay and submit", "Use ChatGPT to: brainstorm angles, explain confusing concepts, draft bullet outlines, suggest counter-arguments. Then the student WRITES the essay themselves in their voice, fact-checks every claim against reliable sources, and discloses AI assistance. AI is a research/thinking partner, not a ghostwriter", "Never use AI at all", "Have AI write it then paraphrase 20%"], ans: 1, why: "Applying responsible use means naming what AI helps with (ideas, explanation, structure) vs. what the student must still do (write, verify, own the argument). Paraphrasing AI output is still plagiarism.", bloom: "apply" },
    { q: "You ask an image generator for \"a photo of a cat.\" It produces a cat with six legs. Apply what you know — why does this happen?", opts: ["The model is broken", "Image models learn pixel patterns associated with \"cat\" — fur, ears, eyes, whiskers — but don't model anatomy. They produce plausible-LOOKING images without a concept of \"correct number of legs.\" Edges of training distribution (unusual poses, occlusion) amplify this. Always verify AI-generated content has physical/anatomical correctness before using", "It's a prank", "Models see everything perfectly"], ans: 1, why: "Applying understanding of generative models: they model appearance, not reality. Anatomy errors, inconsistent shadows, and text gibberish are signatures of models that match patterns without verifying constraints.", bloom: "apply" },
    { q: "A company uses Generative AI to write product descriptions for 10,000 items. Six months later, organic search traffic drops. Analyse likely causes.", opts: ["Google hates AI", "Causes: (a) AI-generated text is often generic, missing specific keywords real shoppers search for. (b) Search engines increasingly detect and de-rank low-effort AI content. (c) Similar phrasing across items triggers duplicate-content penalties. (d) Lack of genuine brand voice reduces dwell time. Fix: AI for first draft, human editor adds specifics and voice, unique per-product details", "AI never works for SEO", "Organic traffic is random"], ans: 1, why: "Analysing the SEO drop means tracing AI-generated content's specific weaknesses (genericity, detection, duplication) and naming the fix (hybrid human+AI workflow). Real analysis produces multiple causes, not a single excuse.", bloom: "analyze" },
    { q: "A teacher argues: \"Generative AI will replace human writing. Students shouldn't bother learning to write.\" Evaluate.", opts: ["Correct", "Flawed. (1) Writing is thinking — the act of composing clarifies ideas. AI skips that mental work. (2) AI can only remix training-data patterns; genuinely original argument still requires a human. (3) Professional contexts (legal, medical, academic) require human accountability. (4) AI-literate humans who can write AND use AI outperform both AI-only and human-only on real tasks. Teaching writing is MORE important, not less", "Writing is obsolete", "AI is always better than humans"], ans: 1, why: "Evaluating the \"writing is obsolete\" claim requires naming writing's cognitive, originality, accountability, and augmentation roles. The strong answer argues for MORE writing education, not less, in the AI era.", bloom: "evaluate" },
    { q: "Design a policy for your class on how students may use Generative AI.", opts: ["Ban everything", "Allowed: brainstorming, explanation of concepts, code review, draft outlines, language polishing for non-native English speakers. Required: disclose any AI use in an appendix (which tool, what prompt, what you changed). Not allowed: submitting AI output unedited as your work, using AI on in-class timed assessments. Oral follow-ups used to verify understanding of submitted work. Rationale: AI literacy is a real skill; academic integrity is a real requirement; the policy honours both", "Allow anything", "No policy"], ans: 1, why: "Designing an AI policy means drawing a workable line: what's allowed, what's required (disclosure), what's forbidden, and a verification mechanism (oral follow-ups). A binary ban or free-for-all fails; a nuanced policy lets both skills and integrity grow.", bloom: "create" },
  ],

  // ─── Topic 10: AI Ethics (Bias, Plagiarism, Deepfakes, Privacy) ───
  10: [
    { q: "Which of the following is the correct definition of an AI \"hallucination\"?", opts: ["The AI physically overheats", "The model generates confident-sounding content that is factually wrong or fabricated — often in specific details (dates, citations, quotes) while sounding authoritative", "The user imagines the output", "A technical error that stops the AI"], ans: 1, why: "Hallucinations are confident errors, often in verifiable specifics (made-up references, incorrect dates). The key danger is confidence: the AI doesn't signal uncertainty.", bloom: "remember" },
    { q: "Why does AI bias exist even when developers don't intentionally program it in?", opts: ["Developers are secretly biased", "AI learns patterns from training data. If historical data reflects human bias (e.g., past hiring favoured one demographic), the model learns that pattern and replicates it. The bias originates in the data, not the code — which makes it harder to detect and fix", "Bias is a marketing myth", "All AI is unbiased"], ans: 1, why: "Understanding bias means recognising that models amplify existing patterns. Clean code running on biased data produces biased output. Fixing it requires auditing data and choosing fairness constraints, not just writing more code.", bloom: "understand" },
    { q: "A student uses ChatGPT to explain a concept, then writes their essay in their own words based on that understanding. Another student copies ChatGPT's output directly. Apply academic integrity rules — which is ethical?", opts: ["Both are plagiarism", "Student 1 used AI as a LEARNING TOOL — ethical, similar to using a tutor. Student 2 submitted AI's work as their own — plagiarism. The test: did YOU produce the ideas and language, or did the AI?", "Both are fine", "Student 2 is fine if they paraphrase"], ans: 1, why: "Applying academic integrity: using AI to understand is like using a textbook (fine). Submitting AI output unchanged (or lightly paraphrased) is representing another's work as yours (plagiarism). The line is about who did the thinking.", bloom: "apply" },
    { q: "A friend wants to share personal health problems with an AI chatbot for advice. Apply privacy thinking — what should they consider before doing so?", opts: ["Share everything freely", "(1) Where does the data go? Most chatbots log conversations for training. (2) Who can access logs? Company employees, potentially subpoena-accessible. (3) Would they be comfortable if this conversation were public? If not, don't type it. (4) Alternatives: local LLMs, telemedicine with privacy guarantees, anonymised phrasing. Default: assume anything typed into a chatbot may be read by someone else", "AI is always private", "Only share with doctors"], ans: 1, why: "Applying privacy thinking to AI chat means tracing where data goes. The convenience of typing anything is deceptive; the audit trail is long. Realistic advice names the alternatives.", bloom: "apply" },
    { q: "A hiring AI denies a disproportionate number of applicants from a specific neighbourhood. The AI was trained on historical hiring decisions. Analyse what went wrong and how to fix it.", opts: ["Random chance", "Historical bias: if past hiring underrepresented that neighbourhood, the model learned \"that neighbourhood = low fit.\" Correlated features (zip code) can smuggle in demographic bias even when demographics are removed. Fixes: (1) audit training data for past bias, (2) remove or correct zip-code correlations, (3) test model outputs across demographics, (4) require human review for high-stakes decisions, (5) apply fairness constraints in training", "AI can't be biased", "Use a different AI"], ans: 1, why: "Analysing algorithmic bias means tracing data → model → outcome, and identifying correlated features that carry bias (zip codes, names). Naming multiple fixes (audit, feature engineering, testing, oversight, constraints) shows depth.", bloom: "analyze" },
    { q: "A company creates deepfake videos of competitors' CEOs saying false things. Evaluate the ethical and legal dimensions.", opts: ["It's fine — free speech", "Flawed on multiple axes. (1) Legally: defamation, fraud, and in some jurisdictions specific deepfake laws. (2) Ethically: non-consensual portrayal, intent to deceive, reputational harm. (3) Practically: erodes trust in all video evidence, harming society beyond the target. Free speech protects opinion, not fabricated attribution. The company faces both lawsuits and social sanction", "Always acceptable", "Only illegal in some countries"], ans: 1, why: "Evaluating deepfakes means naming legal, ethical, and societal harms. \"Free speech\" doesn't cover fabricating attributed statements. The analysis should multiply the individual harm into a systemic one.", bloom: "evaluate" },
    { q: "Design a personal AI-use ethics checklist you'd apply before using any AI tool for important decisions.", opts: ["Skip ethics", "1. OUTPUT: Could the result harm someone if wrong? Fact-check. 2. DATA: Am I typing sensitive info? If yes, use a privacy-respecting alternative. 3. ATTRIBUTION: Am I passing off AI output as my own work? Disclose. 4. BIAS: Is this a decision where historical bias matters (hiring, lending, admissions)? Apply human review. 5. DEPENDENCE: Am I outsourcing thinking I should own? Use AI to augment, not replace, judgment. Run through the list in ~30 seconds before any serious use", "Just use AI freely", "Never use AI"], ans: 1, why: "Designing an ethics checklist means producing a short, practical set of questions covering output quality, privacy, attribution, bias, and dependence. A 5-point checklist is actionable; a vague \"be ethical\" is not.", bloom: "create" },
  ],
};
